  'content/writings/_template-note.mdx':
    "---\n# A note is a short post with no headline. Leave `title` out and the loader\n# derives one from the first sentence for feeds and the writings index.\ndescription: ''\npublished: 2026-01-01T09:00-0800\nlastUpdated: 2026-01-01T09:00-0800\ntags: [note]\ndraft: true\npostType: note\n# Copies of this note on other services (POSSE). Each renders as a\n# u-syndication link under the note.\nsyndication:\n  - name: Instagram\n    url: https://instagram.com/p/...\n# People this note is about or with (person tags). Each renders as a\n# u-category h-card chip and receives a webmention at its url.\n# people:\n#   - name: Jane Doe\n#     url: https://janedoe.example\n# Set inReplyTo to make this note a reply. It renders as u-in-reply-to and the\n# site fetches the target page for reply context.\n# inReplyTo: https://example.com/post\n# Interaction targets. Each one implies its postType when postType is absent.\n# likeOf: https://example.com/post      -> u-like-of\n# repostOf: https://example.com/post    -> u-repost-of\n# bookmarkOf: https://example.com/post  -> u-bookmark-of\n# RSVP to an event. status is one of yes, no, maybe, interested.\n# rsvp:\n#   eventUrl: https://example.com/event\n#   status: yes\n---\n\nWrite the note here. A handle such as @thewilliediaries links to that account\nautomatically.\n",
  'content/writings/_template.mdx':
    "---\n# Articles need a title. Notes, replies, likes, reposts, bookmarks, and RSVPs\n# may leave it out, and the first sentence of the body stands in for it.\ntitle: ''\ndescription: ''\npublished: 2024-02-14T01:01-0800\nlastUpdated: 2024-02-14T01:01-0800\ntags: []\ndraft: true\nfeaturedImage: ''\nfeaturedImageAlt: ''\n# Post kind. One of article (default), note, photo, like, repost, bookmark, rsvp.\n# A reply is any kind with inReplyTo set. See _template-note.mdx for the\n# short-form fields.\npostType: article\n# Optional: reference a series by slug (must exist in content/series/)\n# series:\n#   slug: 'example-series'\n#   part: 1\n# Optional: copies of this post on other services (POSSE). Each renders as a\n# u-syndication link.\n# syndication:\n#   - name: Instagram\n#     url: https://instagram.com/p/...\n# Optional: people this post is about or with (person tags). Each renders as a\n# u-category h-card chip and receives a webmention at its url.\n# people:\n#   - name: Jane Doe\n#     url: https://janedoe.example\n# Optional: the post this one responds to. Renders as u-in-reply-to.\n# inReplyTo: https://example.com/post\n# Optional interaction targets. Setting one also sets the postType when it is\n# absent. They render as u-like-of, u-repost-of, and u-bookmark-of.\n# likeOf: https://example.com/post\n# repostOf: https://example.com/post\n# bookmarkOf: https://example.com/post\n# Optional RSVP. status is one of yes, no, maybe, interested. Renders as\n# p-rsvp with u-in-reply-to on the event.\n# rsvp:\n#   eventUrl: https://example.com/event\n#   status: yes\n---\n",
